//! The Effects store: the continuous effects resolved spells and abilities created.
//!
//! [CR 611.2](https://yawgatog.com/resources/magic-rules/#R6112): "A continuous effect may
//! be generated by the resolution of a spell or ability." Each is one entry: what it
//! affects, what it does (its payload, a resolved kernel type that names no word of a card
//! left to settle), how long it lasts, the card it came from and its timestamp. The rules
//! start one with [`State::start_effect`], which takes what it does with what it does it to
//! as one value ([`Continuous`]), so only a pair that means something can begin. They read
//! them by kind: the layers ask for [`State::layer_effects`], a zone change for
//! [`State::move_replacements`]. A kind with nothing live costs its reader one AND.
//!
//! Built so far: an object, a player and a locked-in set of objects ([`sets`]) as the
//! affected side, and the layer change, the zone-change replacement, the rule change, the
//! permission to cast, the cost change, the regeneration shield ([`regeneration`]), the
//! prevention shield ([`prevention`]), the text change ([`text`]), the player-controlling
//! effect ([`control`]) and the extra turn ([`extra_turn`]) as payloads. The game
//! as a side is designed in the contract and built with its first user.
//!
//! [`State::rule_applies`] is the one question about a rule change, whether a static
//! ability or one of these effects makes it.

use beryl_card::TextChange;

use crate::fixed::Full;
use crate::ids::{CardId, Seat, SlotId};
use crate::layout::{Layout, Queue, Small, Table};
use crate::object::ObjectRef;
use crate::observation::Observation;
use crate::query::Copiable;
use crate::rule_changes::{RuleId, Rules};
use crate::state::State;
use crate::store::{Duration, Ended};
use crate::table::GameTable;

mod change;
pub mod control;
pub mod copy;
pub mod extra_turn;
mod on;
pub mod prevention;
pub mod regeneration;
mod sets;
mod store;
pub mod text;

pub use change::{Characteristics, LayerChange, read_layer};
pub use on::EffectsOn;
pub use prevention::{ChosenSource, Shield, ShieldAt};
use sets::Sets;
pub use sets::{LockedIn, SETS};

/// The continuous effects a [`Small`] game holds at once. One past it stalls the game into
/// [`crate::Large`], whose store grows.
pub const EFFECTS: usize = 64;

/// What a continuous effect does, with what it does it to: the one thing
/// [`State::start_effect`] starts. Each variant is a pair the game has a meaning for, so a
/// layer change on a player or a permission to cast one cannot be written.
///
/// An object is named as it is when the effect begins, and the effect ends with it
/// ([CR 400.7](https://yawgatog.com/resources/magic-rules/#R4007)).
///
/// ```compile_fail
/// use beryl_kernel::Seat;
/// use beryl_kernel::state::{Continuous, LayerChange, Subject};
///
/// // A layer changes a permanent, never a player.
/// let player = Subject::Player(Seat::P0);
/// let pumped: Continuous = Continuous::Layer(player, LayerChange::ModifyPt(1, 1));
/// ```
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Continuous<L: Layout = Small> {
    /// Changes one permanent in a layer (architecture §9). An effect that changes several
    /// is [`State::start_effect_on_set`]'s, which locks them in.
    Layer(ObjectRef<L>, LayerChange),
    /// Replaces a zone change of the object.
    Move(ObjectRef<L>, MoveReplacement),
    /// Changes a rule of the game for a player or for one object
    /// ([CR 613.11](https://yawgatog.com/resources/magic-rules/#R61311)): "Some continuous
    /// effects affect game rules rather than objects." The rule change is one the game's
    /// cards name, by its number ([`crate::GameTable::rule`]).
    Rule(Subject<L>, RuleId),
    /// Lets a player cast the card from the zone it is in.
    Cast(ObjectRef<L>, Permission),
    /// Changes what the spell costs.
    Cost(ObjectRef<L>, CostChange),
    /// A regeneration shield on the permanent ([`regeneration`]).
    Regeneration(ObjectRef<L>),
    /// A prevention shield on a player or a permanent ([`prevention`]).
    Prevent(Subject<L>, Shield<L>),
    /// A copy effect: the object has these copiable values ([CR 707.2]): "When copying an
    /// object, the copy acquires the copiable values of the original object's
    /// characteristics". It applies in layer 1 ([CR 613.1a]): "Rules and effects that modify
    /// copiable values are applied."
    /// The object's own fields name the definition and face ([`crate::state::Flag::Copy`]),
    /// and the entry keeps the exceptions ([`copy`]).
    ///
    /// [CR 707.2]: https://yawgatog.com/resources/magic-rules/#R7072
    /// [CR 613.1a]: https://yawgatog.com/resources/magic-rules/#R6131a
    Copy(ObjectRef<L>, Copiable<L>),
    /// A text change on a spell or a permanent ([`text`]).
    Text(ObjectRef<L>, TextChange),
    /// `controller` controls `controlled` during `controlled`'s next turn ([`control`]).
    Control { controlled: Seat, controller: Seat },
    /// The player takes an extra turn after the current one ([`extra_turn`]).
    ExtraTurn(Seat),
}

impl<L: Layout> Continuous<L> {
    /// What it affects: an object, or the player a rule is changed for.
    #[inline]
    pub fn subject(self) -> Subject<L> {
        match self {
            Continuous::Layer(object, _)
            | Continuous::Move(object, _)
            | Continuous::Cast(object, _)
            | Continuous::Cost(object, _)
            | Continuous::Regeneration(object)
            | Continuous::Copy(object, _)
            | Continuous::Text(object, _) => Subject::Object(object),
            Continuous::Rule(subject, _) | Continuous::Prevent(subject, _) => subject,
            Continuous::Control { controlled, .. } => Subject::Player(controlled),
            Continuous::ExtraTurn(player) => Subject::Player(player),
        }
    }

    /// What it does, as an entry keeps it.
    #[inline]
    fn payload(self) -> Payload<L> {
        match self {
            Continuous::Layer(_, change) => Payload::Layer(change),
            Continuous::Move(_, replacement) => Payload::Move(replacement),
            Continuous::Rule(_, rule) => Payload::Rule(rule),
            Continuous::Cast(_, terms) => Payload::Cast(terms),
            Continuous::Cost(_, change) => Payload::Cost(change),
            Continuous::Regeneration(_) => Payload::Regeneration,
            Continuous::Prevent(_, shield) => Payload::Prevent(shield),
            Continuous::Copy(_, values) => Payload::Copy(values),
            Continuous::Text(_, change) => Payload::Text(change),
            Continuous::Control { controller, .. } => Payload::Control(controller),
            Continuous::ExtraTurn(_) => Payload::ExtraTurn,
        }
    }
}

/// Who a rule of the game is changed for, or asked about ([`State::rule_applies`]): a
/// player, or one object for a rule about itself.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Subject<L: Layout = Small> {
    /// One player: "you may", "target player can't".
    Player(Seat),
    /// One object, as it was when the effect began or as it is asked about.
    Object(ObjectRef<L>),
}

impl<L: Layout> Subject<L> {
    /// The side of an entry that is about it.
    #[inline]
    fn stored(self) -> Affects<L> {
        match self {
            Subject::Player(player) => Affects::Player(player),
            Subject::Object(object) => Affects::object(object),
        }
    }
}

/// The permanents a layer change is on ([`State::layer_effects`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Permanents<L: Layout = Small> {
    /// One, as it was when the effect began.
    One(ObjectRef<L>),
    /// Those of a locked-in set that have not left since
    /// ([CR 611.2c](https://yawgatog.com/resources/magic-rules/#R6112c)): "After that point,
    /// the set won't change." [`State::locked_in`] reads them.
    Set(LockedIn<L>),
}

/// What a continuous effect affects, as an entry keeps it beside its [`Payload`].
///
/// An object is named by one incarnation of its slot, so the effect ends with the object
/// ([CR 400.7](https://yawgatog.com/resources/magic-rules/#R4007)). The fields are the
/// variant's own rather than an [`ObjectRef`] so that every side (a player, a locked-in
/// set, and the game to come) shares its four bytes in [`Small`].
///
/// The two halves are stored apart because together, as one [`Continuous`], an entry would
/// be 32 bytes in [`Small`] and not 24: a layer change is 16 with an alignment of 8. So the
/// store's mutators are what keep the pairs to those that mean something: one takes a
/// [`Continuous`], which has no other, and the other a layer change for a set. A player is
/// affected by a rule change or a prevention shield alone, since a layer changes a permanent
/// and a zone change is an object's. A set is affected by a layer change alone: only a change to
/// characteristics or control locks in what it affects (CR 611.2c), and nothing else that
/// the cards do is one effect on several objects.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Affects<L: Layout = Small> {
    /// One object, as it was when the effect began
    /// ([CR 611.2c](https://yawgatog.com/resources/magic-rules/#R6112c)): "the set of objects
    /// it affects is determined when that continuous effect begins. After that point, the set
    /// won't change."
    Object { slot: L::Slot, incarnation: u16 },
    /// One player: "you may", "target player can't".
    Player(Seat),
    /// Several permanents, those that were there as the effect began and have not left
    /// since ([CR 611.2c](https://yawgatog.com/resources/magic-rules/#R6112c)): "After that
    /// point, the set won't change." [`State::locked_in`] reads them.
    Set(LockedIn<L>),
}

impl<L: Layout> Affects<L> {
    /// The object `r` names.
    #[inline]
    fn object(r: ObjectRef<L>) -> Affects<L> {
        Affects::Object {
            slot: r.slot,
            incarnation: r.incarnation,
        }
    }

    /// The object it affects, if it affects one and no more.
    #[inline]
    pub fn as_object(self) -> Option<ObjectRef<L>> {
        match self {
            Affects::Object { slot, incarnation } => Some(ObjectRef { slot, incarnation }),
            Affects::Player(_) | Affects::Set(_) => None,
        }
    }
}

/// A replacement of where an object goes
/// ([CR 614.1a](https://yawgatog.com/resources/magic-rules/#R6141a)): "Effects that use the
/// word 'instead' are replacement effects."
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum MoveReplacement {
    /// "If it would be put into a graveyard, exile it instead."
    ExileInsteadOfGraveyard,
    /// What paying a flashback cost does to the spell
    /// ([CR 702.34a](https://yawgatog.com/resources/magic-rules/#R70234a)): "If the flashback
    /// cost was paid, exile this card instead of putting it anywhere else any time it would
    /// leave the stack."
    Flashback,
}

/// A permission to cast the affected card from the zone it is in, with the terms a spell
/// cast under it is cast on
/// ([CR 601.3](https://yawgatog.com/resources/magic-rules/#R6013)): "A player can begin to
/// cast a spell only if a rule or effect allows that player to cast it". It is an entry on
/// one incarnation of the card, so it ends when the card leaves that zone
/// ([CR 400.7](https://yawgatog.com/resources/magic-rules/#R4007)), whatever its duration.
///
/// The terms are about the spell, which is a new object: as it is cast the rules start
/// them on it, a [`Continuous::Cost`] for the increase and a [`Continuous::Move`] for the
/// replacement.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Permission {
    /// Who may cast the card, which need not be its owner.
    pub player: Seat,
    /// Generic mana the spell costs more, as in "A spell cast this way costs {2} more to
    /// cast."
    pub increase: u8,
    /// Where the spell goes instead as it leaves the stack: "If that spell would be put
    /// into your graveyard, exile it instead.", or flashback's own.
    pub replacement: Option<MoveReplacement>,
}

impl Permission {
    /// Whether the card has flashback by it, its flashback cost the card's mana cost
    /// ([CR 702.34a](https://yawgatog.com/resources/magic-rules/#R70234a)): "'Flashback
    /// [cost]' means 'You may cast this card from your graveyard if the resulting spell is an
    /// instant or sorcery spell by paying [cost] rather than paying its mana cost'". Paying it
    /// is an alternative cost, so no other can be chosen with it.
    #[inline]
    pub fn is_flashback(self) -> bool {
        self.replacement == Some(MoveReplacement::Flashback)
    }
}

/// A change to what the affected spell costs, applied as its total cost is determined
/// ([CR 601.2f](https://yawgatog.com/resources/magic-rules/#R6012f)): "The total cost is the
/// mana cost or alternative cost (as determined in rule 601.2b), plus all additional costs
/// and cost increases, and minus all cost reductions."
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CostChange {
    /// It costs this much generic mana more.
    Increase(u8),
}

/// A permission to cast in force: the card it is about, its terms, and the card whose
/// spell or ability granted it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Permitted<L: Layout = Small> {
    pub card: ObjectRef<L>,
    pub terms: Permission,
    pub source: L::Card,
}

/// What a continuous effect does, as an entry keeps it beside its [`Affects`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Payload<L: Layout = Small> {
    /// Changes the affected permanent in a layer (architecture §9).
    Layer(LayerChange),
    /// Replaces a zone change of the affected object.
    Move(MoveReplacement),
    /// Changes a rule of the game for what it affects
    /// ([CR 613.11](https://yawgatog.com/resources/magic-rules/#R61311)): "Some continuous
    /// effects affect game rules rather than objects." The rule change is the vocabulary's
    /// own data, which a game numbers ([`crate::GameTable::rule`]): the number is what is
    /// kept, and the affected side is who it applies to.
    Rule(RuleId),
    /// Lets a player cast the affected card from the zone it is in.
    Cast(Permission),
    /// Changes what the affected spell costs.
    Cost(CostChange),
    /// Replaces the next destruction of the affected permanent ([`regeneration`]).
    Regeneration,
    /// Prevents damage to the affected player or permanent ([`prevention`]).
    Prevent(Shield<L>),
    /// Gives the affected object these copiable values ([`copy`]).
    Copy(Copiable<L>),
    /// Changes the affected object's text ([`text`]).
    Text(TextChange),
    /// This player controls the affected player in their next turn ([`control`]).
    Control(Seat),
    /// The affected player takes an extra turn after the current one ([`extra_turn`]).
    ExtraTurn,
}

impl<L: Layout> Payload<L> {
    /// The bit of its kind in a store's [`Kinds`].
    #[inline]
    fn kind(self) -> u16 {
        match self {
            Payload::Layer(_) => Kinds::LAYER,
            Payload::Move(_) => Kinds::MOVE,
            Payload::Rule(_) => Kinds::RULE,
            Payload::Cast(_) => Kinds::CAST,
            Payload::Cost(_) => Kinds::COST,
            Payload::Regeneration => Kinds::REGENERATION,
            Payload::Prevent(_) => Kinds::PREVENTION,
            Payload::Copy(_) => Kinds::COPY,
            Payload::Text(_) => Kinds::TEXT,
            Payload::Control(_) => Kinds::CONTROL,
            Payload::ExtraTurn => Kinds::EXTRA_TURN,
        }
    }
}

/// The kinds of payload among a store's entries: its index by kind, so that a reader of a
/// kind with nothing live stops at one AND.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct Kinds(u16);

impl Kinds {
    const LAYER: u16 = 1 << 0;
    const MOVE: u16 = 1 << 1;
    const RULE: u16 = 1 << 2;
    const CAST: u16 = 1 << 3;
    const COST: u16 = 1 << 4;
    const REGENERATION: u16 = 1 << 5;
    const PREVENTION: u16 = 1 << 6;
    const COPY: u16 = 1 << 7;
    const TEXT: u16 = 1 << 8;
    const CONTROL: u16 = 1 << 9;
    const EXTRA_TURN: u16 = 1 << 10;
}

/// A continuous effect from a resolved spell or ability
/// ([CR 611.2](https://yawgatog.com/resources/magic-rules/#R6112)). A record: the store
/// gives entries back whole.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ContinuousEffect<L: Layout = Small> {
    /// The game index of the card the spell or ability that created it came from, as it was
    /// then. The source may since have left its zone, and once hidden its slot may hold another
    /// card ([CR 611.2a](https://yawgatog.com/resources/magic-rules/#R6112a): the effect lasts
    /// as stated even then), so the effect keeps the card rather than the slot.
    pub source: L::Card,
    /// When it began ([CR 613.7](https://yawgatog.com/resources/magic-rules/#R6137)): "An
    /// effect with an earlier timestamp is applied before an effect with a later timestamp."
    pub timestamp: u16,
    pub duration: Duration,
    pub affected: Affects<L>,
    pub payload: Payload<L>,
}

/// An entry is 24 bytes in [`Small`], whichever side and payload it has: the store's room
/// (the crate's contract, "Stores") counts on it, and it is why an entry keeps the two
/// halves of a [`Continuous`] apart ([`Affects`]).
const _: () = assert!(size_of::<ContinuousEffect<Small>>() == 24);

/// The variant and its fields, as a derived `Hash` would; a canonical hash reads an object's
/// incarnation as how long ago it was current ([`crate::repeats`]).
impl<L: Layout> std::hash::Hash for Affects<L> {
    fn hash<H: std::hash::Hasher>(&self, h: &mut H) {
        std::mem::discriminant(self).hash(h);
        match *self {
            Affects::Object { slot, incarnation } => {
                slot.hash(h);
                crate::repeats::reference(slot.index(), incarnation).hash(h);
            }
            Affects::Player(seat) => seat.hash(h),
            Affects::Set(set) => set.hash(h),
        }
    }
}

/// The fields in order, as a derived `Hash` would; a canonical hash reads the timestamp as
/// its rank ([`crate::repeats`]).
impl<L: Layout> std::hash::Hash for ContinuousEffect<L> {
    fn hash<H: std::hash::Hasher>(&self, h: &mut H) {
        let ContinuousEffect {
            source,
            timestamp,
            duration,
            affected,
            payload,
        } = self;
        source.hash(h);
        crate::repeats::timestamp(*timestamp, true).hash(h);
        duration.hash(h);
        affected.hash(h);
        payload.hash(h);
    }
}

impl<L: Layout> Default for ContinuousEffect<L> {
    fn default() -> Self {
        ContinuousEffect {
            source: L::Card::FIRST,
            timestamp: 0,
            duration: Duration::EndOfTurn,
            affected: Affects::object(ObjectRef::default()),
            payload: Payload::Move(MoveReplacement::ExileInsteadOfGraveyard),
        }
    }
}

/// The Effects store: the entries in the order they began, the sets of objects that
/// entries on several affect, and two indices of the entries, the kinds among them and the
/// rules they change for each player.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Effects<L: Layout = Small> {
    entries: L::Queue<ContinuousEffect<L>, EFFECTS>,
    /// The members of each set an entry names ([`Affects::Set`]).
    sets: Sets<L>,
    kinds: Kinds,
    /// The rules the entries on each player change, so that whether one applies to a
    /// player is one AND ([`State::rule_applies`]).
    rules: L::PerPlayer<Rules>,
}

impl Copy for Effects<Small> {}

/// The entries, and the members of each set one names: the kinds and the players' rules
/// are indices of them, and a hash of a state is a hash of the game.
impl<L: Layout> std::hash::Hash for Effects<L> {
    fn hash<H: std::hash::Hasher>(&self, h: &mut H) {
        self.entries.hash(h);
        for e in self.entries.iter() {
            if let Affects::Set(set) = e.affected {
                self.sets.members(set).hash(h);
            }
        }
    }
}

impl<L: Layout> Effects<L> {
    /// The timestamp of each entry, to number again ([`crate::state::State`]'s timestamps).
    pub(crate) fn timestamps_mut(&mut self) -> impl Iterator<Item = &mut u16> {
        self.entries
            .as_mut_slice()
            .iter_mut()
            .map(|e| &mut e.timestamp)
    }

    /// The entries, if one of them has a payload of a kind in `kinds`; none otherwise.
    #[inline]
    fn of(&self, kinds: u16) -> &[ContinuousEffect<L>] {
        if self.kinds.0 & kinds == 0 {
            return &[];
        }
        self.entries.as_slice()
    }

    /// Ends the entries `keep` refuses, and each whose set has no member left, and says
    /// what that changed.
    #[inline]
    pub(crate) fn end(&mut self, keep: impl Fn(&ContinuousEffect<L>) -> bool) -> Ended {
        let mut done = Ended::default();
        let mut kinds = 0;
        let mut rules: L::PerPlayer<Rules> = Table::filled(Rules::NONE);
        let sets = &mut self.sets;
        self.entries.retain(|e| {
            let mut kept = keep(e);
            if let Affects::Set(set) = e.affected {
                kept &= !sets.members(set).is_empty();
                if !kept {
                    sets.release(set);
                }
            }
            if kept {
                kinds |= e.payload.kind();
                if let Some((player, rule)) = e.player_rule() {
                    rules[player.index()] = rules[player.index()].with(rule);
                }
            } else {
                done.any = true;
                done.layer_input |= matches!(
                    e.payload,
                    Payload::Layer(_) | Payload::Copy(_) | Payload::Text(_)
                );
            }
            kept
        });
        self.sets.trim();
        self.kinds = Kinds(kinds);
        self.rules = rules;
        done
    }

    /// The rule changes the entries make for exactly `affected`.
    #[inline]
    fn rules_on(&self, affected: Affects<L>) -> Rules {
        self.of(Kinds::RULE)
            .iter()
            .fold(Rules::NONE, |rules, e| match e.payload {
                Payload::Rule(rule) if e.affected == affected => rules.with(rule),
                _ => rules,
            })
    }
}

impl<L: Layout> ContinuousEffect<L> {
    /// The player it changes a rule for and the rule, if that is what it does: what the
    /// store's index of the players' rules holds of it.
    #[inline]
    fn player_rule(&self) -> Option<(Seat, RuleId)> {
        match (self.affected, self.payload) {
            (Affects::Player(player), Payload::Rule(rule)) => Some((player, rule)),
            _ => None,
        }
    }

    /// The permanents it changes in a layer and the change, if that is what it does.
    #[inline]
    fn layer_change(&self) -> Option<(Permanents<L>, LayerChange)> {
        match (self.affected, self.payload) {
            (Affects::Object { slot, incarnation }, Payload::Layer(change)) => {
                Some((Permanents::One(ObjectRef { slot, incarnation }), change))
            }
            (Affects::Set(set), Payload::Layer(change)) => Some((Permanents::Set(set), change)),
            _ => None,
        }
    }

    /// The permission to cast it is, if that is what it does.
    #[inline]
    fn permission(&self) -> Option<Permitted<L>> {
        match (self.affected, self.payload) {
            (Affects::Object { slot, incarnation }, Payload::Cast(terms)) => Some(Permitted {
                card: ObjectRef { slot, incarnation },
                terms,
                source: self.source,
            }),
            _ => None,
        }
    }
}

impl<L: Layout> State<L> {
    /// Starts a continuous effect of the card `source`, with the next timestamp
    /// ([CR 611.2](https://yawgatog.com/resources/magic-rules/#R6112)): "A continuous effect
    /// may be generated by the resolution of a spell or ability."
    /// [CR 613.7](https://yawgatog.com/resources/magic-rules/#R6137): an effect's timestamp
    /// is the time it was created. An object it affects must be current. The layer results
    /// are stale from here if it changes a layer. No event: the rules announce what the
    /// effect is part of, as they do a change of control.
    #[inline]
    pub fn start_effect(
        &mut self,
        source: L::Card,
        effect: Continuous<L>,
        duration: Duration,
    ) -> Result<(), Full> {
        let timestamp = self.take_timestamp();
        self.push_effect(source, effect, duration, timestamp)
    }

    /// Starts several continuous effects of the card `source` that begin together, with one
    /// timestamp ([CR 613.7](https://yawgatog.com/resources/magic-rules/#R6137)): the
    /// changes of control of an exchange
    /// ([CR 701.12b](https://yawgatog.com/resources/magic-rules/#R70112b): "each of those
    /// players simultaneously gains control of the permanent that was controlled by the other
    /// player"). Each is as [`State::start_effect`] starts it.
    ///
    /// # Errors
    ///
    /// When the store is full; the effects before the one that did not fit have begun.
    #[inline]
    pub fn start_effects(
        &mut self,
        source: L::Card,
        effects: &[Continuous<L>],
        duration: Duration,
    ) -> Result<(), Full> {
        let timestamp = self.take_timestamp();
        for &effect in effects {
            self.push_effect(source, effect, duration, timestamp)?;
        }
        Ok(())
    }

    /// Stores a continuous effect that began at `timestamp`.
    #[inline]
    fn push_effect(
        &mut self,
        source: L::Card,
        effect: Continuous<L>,
        duration: Duration,
        timestamp: u16,
    ) -> Result<(), Full> {
        let subject = effect.subject();
        let payload = effect.payload();
        let pushed = self.effects.entries.push(ContinuousEffect {
            source,
            timestamp,
            duration,
            affected: subject.stored(),
            payload,
        });
        if pushed.is_ok() {
            self.effects.kinds.0 |= payload.kind();
            match effect {
                Continuous::Rule(Subject::Player(player), rule) => {
                    let rules = &mut self.effects.rules[player.index()];
                    *rules = rules.with(rule);
                }
                Continuous::Prevent(Subject::Player(_), _)
                | Continuous::Control { .. }
                | Continuous::ExtraTurn(_) => {}
                Continuous::Layer(object, _)
                | Continuous::Move(object, _)
                | Continuous::Rule(Subject::Object(object), _)
                | Continuous::Prevent(Subject::Object(object), _)
                | Continuous::Cast(object, _)
                | Continuous::Cost(object, _)
                | Continuous::Regeneration(object)
                | Continuous::Text(object, _) => {
                    debug_assert!(self.is_current(object));
                    self.keyed.insert(object.slot);
                }
                Continuous::Copy(object, values) => {
                    debug_assert!(self.is_current(object));
                    self.keyed.insert(object.slot);
                    self.take_copied_values(object, values)?;
                }
            }
        }
        if matches!(effect, Continuous::Layer(..) | Continuous::Text(..)) {
            self.flags.derived_dirty = true;
        }
        pushed
    }

    /// Every continuous effect, in the order they began: for tools, tests and a view. The
    /// rules ask by kind.
    #[inline]
    pub fn effects(&self) -> &[ContinuousEffect<L>] {
        self.effects.entries.as_slice()
    }

    /// The effects that change a permanent in a layer, each with the permanents it is on
    /// and its change, in the order they began. With none live, one AND.
    #[inline]
    pub fn layer_effects(
        &self,
    ) -> impl Iterator<Item = (&ContinuousEffect<L>, Permanents<L>, LayerChange)> {
        self.effects
            .of(Kinds::LAYER)
            .iter()
            .filter_map(|e| e.layer_change().map(|(on, change)| (e, on, change)))
    }

    /// The replacements of where `object` goes. With none live on any object, one AND.
    #[inline]
    pub fn move_replacements(
        &self,
        object: ObjectRef<L>,
    ) -> impl Iterator<Item = MoveReplacement> + '_ {
        let affected = Affects::object(object);
        self.effects
            .of(Kinds::MOVE)
            .iter()
            .filter_map(move |e| match e.payload {
                Payload::Move(replacement) if e.affected == affected => Some(replacement),
                _ => None,
            })
    }

    /// The permissions to cast, in the order they began: who may cast which card from a
    /// zone it could not otherwise be cast from, and on what terms. Each names its card's
    /// current object (the store's invariant). With none live, one AND.
    #[inline]
    pub fn cast_permissions(&self) -> impl Iterator<Item = Permitted<L>> + '_ {
        self.effects
            .of(Kinds::CAST)
            .iter()
            .filter_map(ContinuousEffect::permission)
    }

    /// The generic mana the cost changes on the spell `object` add to its cost
    /// ([CR 601.2f](https://yawgatog.com/resources/magic-rules/#R6012f): "plus all additional
    /// costs and cost increases"). With no cost change live on any object, one AND.
    #[inline]
    pub fn cost_increase(&self, object: ObjectRef<L>) -> u8 {
        let affected = Affects::object(object);
        self.effects
            .of(Kinds::COST)
            .iter()
            .filter(|e| e.affected == affected)
            .fold(0, |total, e| match e.payload {
                Payload::Cost(CostChange::Increase(n)) => total.saturating_add(n),
                _ => total,
            })
    }

    /// The rule changes in force for `player` now, whoever makes them: a static ability of
    /// a permanent ([CR 604.1](https://yawgatog.com/resources/magic-rules/#R6041): "Static
    /// abilities do something all the time rather than being activated or triggered.") or
    /// the continuous effect of a resolved spell or ability
    /// ([CR 613.11](https://yawgatog.com/resources/magic-rules/#R61311): "Some continuous
    /// effects affect game rules rather than objects."). One OR of two sets: those the
    /// permanents' static abilities make for them, which the layers found with control
    /// settled, and those of the effects on them, which this store keeps as they start and
    /// end. A check ANDs it with the rule changes of its kind
    /// ([`crate::GameTable::rules_of`]).
    ///
    /// # Panics
    ///
    /// In debug builds, while the layer results are stale.
    #[inline]
    pub fn rules_for(&self, player: Seat) -> Rules {
        debug_assert!(!self.flags.derived_dirty, "rules read while dirty");
        let i = player.index();
        self.static_rules[i].union(self.effects.rules[i])
    }

    /// The rule changes resolved effects make for the object `object` alone, one AND while
    /// no effect changes a rule. Its own static abilities' are its copiable values'
    /// ([`crate::Copiable::rules`]), which a face-down permanent has none of
    /// ([CR 708.2](https://yawgatog.com/resources/magic-rules/#R7082)).
    #[inline]
    pub fn effect_rules_on(&self, object: ObjectRef<L>) -> Rules {
        self.effects.rules_on(Affects::object(object))
    }

    /// Whether the rule change the game numbered `rule` applies to `to` now, a player or a
    /// permanent, whoever makes it: for tools and tests. The rules ask for the sets, by
    /// kind ([`State::rules_for`], [`State::effect_rules_on`]).
    ///
    /// # Panics
    ///
    /// In debug builds, for a player while the layer results are stale.
    #[inline]
    pub fn rule_applies(&self, t: &GameTable, rule: RuleId, to: Subject<L>) -> bool {
        match to {
            Subject::Player(player) => self.rules_for(player).contains(rule),
            Subject::Object(object) => {
                let own = self.definition(object.slot).rules(t);
                own.without(t.player_rules())
                    .union(self.effect_rules_on(object))
                    .contains(rule)
            }
        }
    }
}

impl<'a, L: Layout> Observation<'a, L> {
    /// The continuous effects, in the order they began. Every one is public: a spell or
    /// ability resolves in the open, and what it affects is an object every player sees or
    /// a slot, which is a public handle.
    pub fn effects(&self) -> &'a [ContinuousEffect<L>] {
        self.shown().effects()
    }

    /// Who may cast which card from a zone it could not otherwise be cast from, and on what
    /// terms: public, as the effects that grant them are. A card exiled until someone casts
    /// it is face up ([CR 406.3](https://yawgatog.com/resources/magic-rules/#R4063): "Exiled
    /// cards are, by default, kept face up and may be examined by any player at any time").
    pub fn cast_permissions(&self) -> impl Iterator<Item = Permitted<L>> + 'a {
        self.shown().cast_permissions()
    }
}

